import * as fs from 'node:fs';
import * as path from 'node:path';
type IconMode = 'claude' | 'antigravity';
interface IconWindow { isDestroyed(): boolean; setIcon?(icon: unknown): void; setAppDetails?(options: Record<string, unknown>): void }
interface IconHost { windows(): IconWindow[]; image(data: string): { isEmpty(): boolean }; log?(mode: IconMode, count: number): void; taskbar?(win: IconWindow, mode: IconMode, image: unknown): void }
const CLAUGRAVITY_DATA = 'data:image/png;base64,';
const ORIGINAL_DATA = 'data:image/png;base64,';
export function createThemeIconController(host: IconHost, initial: IconMode = 'antigravity') {
  let mode = initial;
  const applied = new WeakMap<IconWindow, IconMode>();
  const images = new Map<IconMode, ReturnType<IconHost['image']>>();
  function applyWindow(win: IconWindow, force = false): number {
    if (win.isDestroyed() || (!force && applied.get(win) === mode)) return 0;
    let image = images.get(mode);
    if (!image) {
      image = host.image(mode === 'claude' ? CLAUGRAVITY_DATA : ORIGINAL_DATA);
      if (image.isEmpty()) throw new Error('Theme icon could not be loaded');
      images.set(mode, image);
    }
    win.setIcon?.(image); host.taskbar?.(win, mode, image); applied.set(win, mode); return 1;
  }
  return {
    apply(value: string) {
      mode = value === 'claude' ? 'claude' : 'antigravity';
      let changed = 0;
      for (const win of host.windows()) changed += applyWindow(win);
      if (changed) host.log?.(mode, changed);
      return { mode, changed };
    },
    windowCreated(win: IconWindow) { return applyWindow(win, true); },
  };
}
export function pngToIco(png: Buffer): Buffer {
  const header = Buffer.alloc(22);
  header.writeUInt16LE(1, 2); header.writeUInt16LE(1, 4);
  header.writeUInt16LE(1, 10); header.writeUInt16LE(32, 12);
  header.writeUInt32LE(png.length, 14); header.writeUInt32LE(22, 18);
  return Buffer.concat([header, png]);
}
let shared: ReturnType<typeof createThemeIconController> | undefined;
export function installThemeIcons(): void {
  if (shared) return;
  const { app, BrowserWindow, nativeImage } = require('electron');
  const { loadPoolConfig } = require('./accountPool');
  const initial = loadPoolConfig().uiThemeMode === 'claude' ? 'claude' : 'antigravity';
  let claugravityIco: string | undefined;
  shared = createThemeIconController({ windows: () => BrowserWindow.getAllWindows(), image: (data) => nativeImage.createFromDataURL(data),
    log: (mode, count) => console.log(`[ThemeIcon] ${mode === 'claude' ? 'Claugravity' : 'Antigravity original'} applied to ${count} window(s)`),
    taskbar: (win, mode, image: any) => {
      if (process.platform === 'darwin') { app.dock?.setIcon(image); return; }
      if (process.platform !== 'win32' || !win.setAppDetails) return;
      if (mode === 'claude' && !claugravityIco) {
        const folder = path.join(app.getPath('userData'), 'theme-icons');
        fs.mkdirSync(folder, { recursive: true });
        claugravityIco = path.join(folder, 'Claugravity-2.1.11.ico');
        fs.writeFileSync(claugravityIco, pngToIco(image.resize({width:256,height:256,quality:'best'}).toPNG()));
      }
      win.setAppDetails({
        appId: mode === 'claude' ? 'electron.app.Claugravity' : 'electron.app.Antigravity',
        appIconPath: mode === 'claude' ? claugravityIco : process.execPath,
        appIconIndex: 0,
        relaunchCommand: '"' + process.execPath + '"',
        relaunchDisplayName: mode === 'claude' ? 'Claugravity' : 'Antigravity',
      });
      console.log(`[ThemeIcon] Windows taskbar: ${mode}`);
    },
  }, initial);
  app.on('browser-window-created', (_event: unknown, win: any) => {
    shared?.windowCreated(win);
    win.once('ready-to-show', () => { if (!win.isDestroyed()) shared?.windowCreated(win); });
  });
  void app.whenReady().then(() => shared?.apply(initial)).catch((error: unknown) => console.warn('[ThemeIcon]', error));
}
export function applyThemeIcon(mode: string): void {
  installThemeIcons(); shared!.apply(mode);
}
